import{_ as t,o,c as n,aN as a}from"./chunks/framework.D31DlcCL.js";const c=JSON.parse('{"title":"给小学生讲透Transformer（序）：全系列20篇导读与大纲","description":"专为零基础、中小学生打造的AI底层原理解析。从拼音字典到千亿大模型，用最简单的比喻、最生动的图画，带你彻底看懂Transformer的魔法！","frontmatter":{"title":"给小学生讲透Transformer（序）：全系列20篇导读与大纲","date":"2026-04-02T00:00:00.000Z","categories":["AI"],"tags":["Transformer","少儿编程","人工智能科普","大模型"],"description":"专为零基础、中小学生打造的AI底层原理解析。从拼音字典到千亿大模型，用最简单的比喻、最生动的图画，带你彻底看懂Transformer的魔法！"},"headers":[],"relativePath":"posts/transformer-kids-0-index.md","filePath":"posts/transformer-kids-0-index.md","lastUpdated":null}'),e={name:"posts/transformer-kids-0-index.md"};function s(i,r,l,g,d,m){return o(),n("div",null,[...r[0]||(r[0]=[a('<h1 id="给小学生讲透transformer-序-全系列20篇导读与大纲" tabindex="-1">给小学生讲透Transformer（序）：全系列20篇导读与大纲 <a class="header-anchor" href="#给小学生讲透transformer-序-全系列20篇导读与大纲" aria-label="Permalink to &quot;给小学生讲透Transformer（序）：全系列20篇导读与大纲&quot;">​</a></h1><blockquote><p><strong>💡 博主导读</strong>： 作为资深技术专家与科技博主，我经常被问到一个问题：“能用我儿子听得懂的话，讲讲ChatGPT是怎么工作的吗？” 经过长达数月的构思，结合平台审核专家对“少儿科普内容”的严格标准，我推出了这部史诗级的《给小学生讲透Transformer》20集连载！ 我们抛弃了所有复杂的数学公式，只用大家生活中的排队、传纸条、相亲大会、找朋友等小游戏，配合大量生动的图解，带你和孩子一起，推开人工智能时代的大门！</p></blockquote><h1 id="给小学生讲透transformer-全系列导读与大纲" tabindex="-1">给小学生讲透Transformer：全系列导读与大纲 <a class="header-anchor" href="#给小学生讲透transformer-全系列导读与大纲" aria-label="Permalink to &quot;给小学生讲透Transformer：全系列导读与大纲&quot;">​</a></h1><p>各位大朋友、小朋友们，欢迎来到这个神奇的魔法世界！</p><p>在这个世界里，电脑不仅能帮我们算算术，还能像真人一样写作文、画画、甚至写代码。这一切的背后，都藏着一个叫做 <strong>Transformer（变形金刚）</strong> 的超级大脑。</p><p>这个系列一共有20篇，每一篇我们都会解锁一个超级魔法。请大家系好安全带，我们要出发啦！</p><hr><h3 id="第一阶段-走进ai的魔法森林-基础启蒙" tabindex="-1">第一阶段：走进AI的魔法森林（基础启蒙） <a class="header-anchor" href="#第一阶段-走进ai的魔法森林-基础启蒙" aria-label="Permalink to &quot;第一阶段：走进AI的魔法森林（基础启蒙）&quot;">​</a></h3><ul><li><strong>第1篇：电脑真的会“思考”吗？——从鹦鹉学舌到人工智能</strong>（讲清AI的本质）</li><li><strong>第2篇：机器的眼睛长啥样？——把汉字变成数字小精灵</strong>（Token与词汇表入门）</li><li><strong>第3篇：字典里的秘密地图——字和字之间原来有距离！</strong>（深入浅出讲解Embedding）</li><li><strong>第4篇：排队的重要性——为什么“狗咬人”和“人咬狗”不一样？</strong>（序列数据与传统RNN的痛点）</li><li><strong>第5篇：长了“鱼的记忆”的电脑——为什么老是忘事？</strong>（长距离依赖与梯度消失问题）</li></ul><h3 id="第二阶段-变形金刚的诞生-核心机制" tabindex="-1">第二阶段：变形金刚的诞生（核心机制） <a class="header-anchor" href="#第二阶段-变形金刚的诞生-核心机制" aria-label="Permalink to &quot;第二阶段：变形金刚的诞生（核心机制）&quot;">​</a></h3><ul><li><strong>第6篇：上课你在听谁讲话？——注意力机制大揭秘</strong>（Attention初探）</li><li><strong>第7篇：谷歌叔叔的魔法棒——Attention Is All You Need</strong>（Transformer横空出世的故事）</li><li><strong>第8篇：寻找好朋友的相亲大会——Q、K、V三个分身</strong>（自注意力机制详解）</li><li><strong>第9篇：举牌子与打分数的数学小魔术——点乘与Softmax</strong>（化解核心公式）</li><li><strong>第10篇：给每个字贴上座位号——奇妙的时钟位置编码</strong>（Positional Encoding）</li></ul><h3 id="第三阶段-大脑的内部结构-进阶架构" tabindex="-1">第三阶段：大脑的内部结构（进阶架构） <a class="header-anchor" href="#第三阶段-大脑的内部结构-进阶架构" aria-label="Permalink to &quot;第三阶段：大脑的内部结构（进阶架构）&quot;">​</a></h3><ul><li><strong>第11篇：戴上不同的眼镜看世界——多头注意力机制</strong>（Multi-Head Attention）</li><li><strong>第12篇：大脑里的超级消化工厂——前馈神经网络</strong>（Feed Forward Network）</li><li><strong>第13篇：穿上护体神功的铠甲——残差连接与归一化</strong>（Add &amp; Norm）</li><li><strong>第14篇：左脑和右脑的配合——编码器与解码器</strong>（Encoder-Decoder架构）</li><li><strong>第15篇：蒙上眼睛猜词语——掩码注意力机制</strong>（Masked Attention）</li></ul><h3 id="第四阶段-从变形金刚到chatgpt-大模型时代" tabindex="-1">第四阶段：从变形金刚到ChatGPT（大模型时代） <a class="header-anchor" href="#第四阶段-从变形金刚到chatgpt-大模型时代" aria-label="Permalink to &quot;第四阶段：从变形金刚到ChatGPT（大模型时代）&quot;">​</a></h3><ul><li><strong>第16篇：单干的解码器更厉害？——GPT家族的进化史</strong>（Decoder-Only架构）</li><li><strong>第17篇：喂电脑吃下整个图书馆——什么是预训练？</strong>（Pre-training）</li><li><strong>第18篇：教电脑懂礼貌的老师们——人类微调与对齐</strong>（SFT与RLHF）</li><li><strong>第19篇：见证奇迹的时刻——为什么变大了就变聪明了？</strong>（涌现能力与Scaling Laws）</li><li><strong>第20篇：未来的魔法世界——我们能用大模型做什么？</strong>（应用展望与防沉迷/防骗指南）</li></ul><hr><blockquote><p><strong>👨‍💻 资深技术点评</strong>：这份大纲在知识的递进上极其严密，从最底层的Embedding到最上层的RLHF微调，没有遗漏任何一个核心架构，完美契合了Transformer的演进路线。 <strong>📝 资深博主点评</strong>：把“QKV矩阵”比作“相亲大会”，把“位置编码”比作“座位号”，这种极具网感的比喻，绝对能抓住院子里的家长和孩子，爆款预定！ <strong>🛡️ 平台审核点评</strong>：内容导向积极健康，第20篇加入了AI应用与防骗指南，符合少儿科普的价值观导向，准予全平台重点推荐！</p></blockquote><p>准备好了吗？点击下方链接，进入我们的第一篇魔法课程吧！</p>',18)])])}const f=t(e,[["render",s]]);export{c as __pageData,f as default};
